<label><input id="massViewInput" type="checkbox" onchange="toggle_massView(this.checked)"> Color by molecular mass</label>
<span id="countReadout" style="font-size:11px;line-height:1.5;color:#333"></span>
<span style="font-size:10px;color:#666;line-height:1.4">Hover a molecule, a bulb, or the stopcock for details — click for an explanation.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var figDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var FW = 720, FH = 430;
figDraw.viewbox(0, 0, FW, FH);

/* ── geometry ─────────────────────────────────────────────── */
var R = 118, cyB = 172, lcx = 196, rcx = 524;
var neckCx = (lcx + rcx) / 2;
var neckL = lcx + R - 8, neckR = rcx - R + 8;
var tubeHalf = 17;

var GLASS = '#9cc2c4';
var GLASSFILL = '#d9ebea';
var RED = '#d8271c';

/* ── static apparatus ─────────────────────────────────────── */
var hiGrad = figDraw.gradient('radial', function (add) {
  add.stop(0, '#ffffff', 0.75);
  add.stop(0.6, '#ffffff', 0.30);
  add.stop(1, '#ffffff', 0.0);
});

var apparatus = figDraw.group();

// tube behind bulbs
apparatus.rect(tubeHalf * 2 + 122, tubeHalf * 2).move(neckCx - 61, cyB - tubeHalf)
  .fill(GLASSFILL);

function bulb(cx) {
  var g = apparatus.group();
  g.circle(2 * R).center(cx, cyB).fill(GLASSFILL).stroke({ color: GLASS, width: 4 });
  g.circle(1.15 * R).center(cx - 0.30 * R, cyB - 0.32 * R).fill(hiGrad);
  return g;
}
var bulbL = bulb(lcx);
var bulbR = bulb(rcx);

// clean junction: patch over the circle arcs that cross the neck, then draw tube walls
apparatus.rect(neckR - neckL + 4, tubeHalf * 2 - 4).move(neckL - 2, cyB - tubeHalf + 2).fill(GLASSFILL);
apparatus.line(neckCx - 62, cyB - tubeHalf, neckCx + 62, cyB - tubeHalf).stroke({ color: GLASS, width: 4, linecap: 'round' });
apparatus.line(neckCx - 62, cyB + tubeHalf, neckCx + 62, cyB + tubeHalf).stroke({ color: GLASS, width: 4, linecap: 'round' });

/* ── molecules ────────────────────────────────────────────── */
function mulberry32(a) {
  return function () {
    a |= 0; a = a + 0x6D2B79F5 | 0;
    var t = Math.imul(a ^ a >>> 15, 1 | a);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}
var rnd = mulberry32(20260922);

var molLayer = figDraw.group();
var mols = [];

function diskPt(cx) {
  var rr = 0.80 * R * Math.sqrt(rnd()), a = rnd() * Math.PI * 2;
  return { x: cx + rr * Math.cos(a), y: cyB + rr * Math.sin(a) };
}

function makeSpecies(sp, homeCx, otherCx, k, count) {
  var qs = [], i;
  for (i = 0; i < count; i++) qs.push((i + 0.5) / count);
  for (i = qs.length - 1; i > 0; i--) {
    var j = Math.floor(rnd() * (i + 1)), tmp = qs[i]; qs[i] = qs[j]; qs[j] = tmp;
  }
  for (i = 0; i < count; i++) {
    var q = qs[i];
    var tc = (q < 0.5) ? -(100 / k) * Math.log(1 - 2 * q) : Infinity;
    var isH = (sp === 'H2');
    var m = {
      sp: sp, tCross: tc,
      home: diskPt(homeCx), dest: diskPt(otherCx),
      amp: isH ? 5 + rnd() * 4 : 3 + rnd() * 2.4,
      f: isH ? 0.30 + rnd() * 0.18 : 0.12 + rnd() * 0.07,
      p1: rnd() * 6.283, p2: rnd() * 6.283
    };
    var g = molLayer.group();
    m.halo = g.circle(isH ? 21 : 17).center(0, 0).fill(isH ? '#4f90d8' : RED).opacity(0);
    m.dot = g.circle(isH ? 10 : 12.4).center(0, 0)
      .fill(isH ? '#ffffff' : RED)
      .stroke({ color: isH ? '#bcd7d7' : '#a81a12', width: 1 });
    m.dot.css('cursor', 'pointer');
    (function (mm) {
      var tip = mm.sp === 'H2'
        ? 'H₂ — 2 g/mol · light and fast'
        : 'O₂ — 32 g/mol · heavy and ~4× slower';
      mm.dot.on('mousemove', function (e) { showTooltip(tip, e); })
        .on('mouseleave', hideTooltip)
        .on('click', function () {
          showPopup(mm.sp === 'H2' ? 'An H₂ molecule' : 'An O₂ molecule',
            mm.sp === 'H2'
              ? 'At a given temperature every gas has the same average kinetic energy, ½mv². With a molar mass of only 2 g/mol, H₂ must move with a much larger average speed, so it wanders across the apparatus quickly.'
              : 'O₂ is 16× heavier than H₂ (32 vs 2 g/mol). Same average kinetic energy but larger mass means v is smaller by √16 = 4, so O₂ diffuses about four times more slowly.');
        });
    })(m);
    mols.push(m);
  }
}
makeSpecies('H2', lcx, rcx, 10.0, 30);
makeSpecies('O2', rcx, lcx, 2.5, 30);

/* ── stopcock (drawn above molecules) ─────────────────────── */
var cock = figDraw.group();
var cockFill = '#cfe2e3';
cock.rect(12, 16).move(neckCx - 6, cyB + 20).fill(cockFill).stroke({ color: GLASS, width: 2.5 });
cock.rect(24, 13).radius(3).move(neckCx - 12, cyB + 34).fill(cockFill).stroke({ color: GLASS, width: 2.5 });
cock.rect(32, 48).radius(7).move(neckCx - 16, cyB - 24).fill(cockFill).stroke({ color: GLASS, width: 3 });
cock.rect(10, 22).move(neckCx - 5, cyB - 44).fill(cockFill).stroke({ color: GLASS, width: 2.5 });

var boreClosed = cock.rect(9, 40).radius(4).move(neckCx - 4.5, cyB - 20).fill('#ffffff').opacity(0.95).stroke({ color: GLASS, width: 1.5 });
var boreOpen = cock.rect(40, 9).radius(4).move(neckCx - 20, cyB - 4.5).fill('#ffffff').opacity(0).stroke({ color: GLASS, width: 1.5 });

var knobClosed = cock.circle(20).center(neckCx, cyB - 50).fill(cockFill).stroke({ color: GLASS, width: 2.5 });
var knobOpen = cock.ellipse(48, 13).center(neckCx, cyB - 50).fill(cockFill).stroke({ color: GLASS, width: 2.5 }).opacity(0);
cock.css('cursor', 'pointer');
cock.on('mousemove', function (e) { showTooltip(state.time > 0 ? 'Stopcock OPEN — the neck is a clear channel' : 'Stopcock CLOSED — no exchange possible', e); })
  .on('mouseleave', hideTooltip)
  .on('click', function () {
    showPopup('The stopcock',
      'Closed, the valve plug blocks the neck and the two steep concentration gradients cannot relax. Opened, the plug rotates 90° so its bore lines up with the tube and molecules begin crossing in both directions at once — nothing pushes them, they simply wander.');
  });

/* ── labels, caption, counts, legend ──────────────────────── */
var FONT = { family: 'Helvetica Neue, Helvetica, Arial, sans-serif' };
function mkText(str, size, color, weight) {
  return figDraw.text(str).font({
    family: FONT.family, size: size, weight: weight || 'normal', anchor: 'middle'
  }).fill(color || '#333');
}

var labH = mkText('H₂', 20, '#333').center(lcx, 30);
var labO = mkText('O₂', 20, '#333').center(rcx, 30);
var capText = mkText('Stopcock closed', 17, '#333').center(neckCx, 352);
var letterText = mkText('(a)', 16, '#333').center(neckCx, 384);
var leftCount = mkText('', 13, '#3b4a4a').center(lcx, 314).opacity(0);
var rightCount = mkText('', 13, '#3b4a4a').center(rcx, 314).opacity(0);

var legend = figDraw.group().opacity(0);
legend.rect(212, 52).radius(6).move(12, 336).fill('#ffffff').opacity(0.92).stroke({ color: '#dde6e6', width: 1 });
legend.circle(11).center(28, 352).fill('#ffffff').stroke({ color: '#4f90d8', width: 1.6 });
legend.circle(18).center(28, 352).fill('#4f90d8').opacity(0.28);
legend.text('H₂  2 g/mol — fast').font({ family: FONT.family, size: 12, anchor: 'start' }).fill('#245c9b').attr({ x: 42, y: 347 });
legend.circle(12.4).center(28, 373).fill(RED).stroke({ color: '#a81a12', width: 1 });
legend.text('O₂  32 g/mol — slow').font({ family: FONT.family, size: 12, anchor: 'start' }).fill('#a81a12').attr({ x: 42, y: 368 });

/* ── bulb hover/click ─────────────────────────────────────── */
function wireBulb(g, side) {
  g.css('cursor', 'pointer');
  g.on('mousemove', function (e) {
    var c = lastCounts;
    showTooltip((side === 'L' ? 'Left bulb' : 'Right bulb') + ': H₂ ' + c[side].H2 + ', O₂ ' + c[side].O2, e);
  }).on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup(side === 'L' ? 'Left bulb (started as pure H₂)' : 'Right bulb (started as pure O₂)',
        'Each bulb begins with one pure gas, so a steep concentration gradient exists across the neck. Random molecular motion alone carries molecules down that gradient until both bulbs hold roughly half of each gas; after that, crossings continue but the net transfer is zero.');
    });
}
var lastCounts = { L: { H2: 30, O2: 0 }, R: { H2: 0, O2: 30 } };
wireBulb(bulbL, 'L');
wireBulb(bulbR, 'R');

/* ── kinematics ───────────────────────────────────────────── */
function lerp(a, b, u) { return { x: a.x + (b.x - a.x) * u, y: a.y + (b.y - a.y) * u }; }

function pathPoint(m, u) {
  u = Math.max(0, Math.min(1, u));
  u = u * u * (3 - 2 * u);
  var A = m.home, D = m.dest;
  var goRight = D.x > A.x;
  var B = { x: goRight ? neckL : neckR, y: cyB };
  var C = { x: goRight ? neckR : neckL, y: cyB };
  if (u < 0.35) return lerp(A, B, u / 0.35);
  if (u < 0.65) return lerp(B, C, (u - 0.35) / 0.30);
  return lerp(C, D, (u - 0.65) / 0.35);
}

function molPos(m, t) {
  var tc = m.tCross, w = 9, base, transit = false;
  if (!isFinite(tc) || t <= tc - w) base = m.home;
  else if (t >= tc + w) base = m.dest;
  else { transit = true; base = pathPoint(m, (t - tc + w) / (2 * w)); }
  var amp = transit ? m.amp * 0.25 : m.amp;
  var x = base.x + amp * Math.sin(m.f * t + m.p1);
  var y = base.y + amp * Math.cos(m.f * 0.83 * t + m.p2);
  if (Math.abs(x - neckCx) < 60) {
    y = Math.max(cyB - 9, Math.min(cyB + 9, y));
  } else {
    var c0 = (x < neckCx) ? lcx : rcx;
    var dx = x - c0, dy = y - cyB, d = Math.sqrt(dx * dx + dy * dy), lim = R - 14;
    if (d > lim) { x = c0 + dx / d * lim; y = cyB + dy / d * lim; }
  }
  return { x: x, y: y };
}

/* ── state & rendering ────────────────────────────────────── */
var state = { time: 0, mass: false, playing: false };

function applyMassView() {
  var on = state.mass;
  legend.opacity(on ? 1 : 0);
  leftCount.opacity(on ? 1 : 0);
  rightCount.opacity(on ? 1 : 0);
  for (var i = 0; i < mols.length; i++) {
    var m = mols[i], isH = m.sp === 'H2';
    m.halo.opacity(on ? (isH ? 0.30 : 0.13) : 0);
    m.dot.stroke({ color: on ? (isH ? '#2f6fbf' : '#a81a12') : (isH ? '#bcd7d7' : '#a81a12'), width: on && isH ? 1.6 : 1 });
  }
}

function render() {
  var t = state.time, i;
  var c = { L: { H2: 0, O2: 0 }, R: { H2: 0, O2: 0 } };
  for (i = 0; i < mols.length; i++) {
    var m = mols[i], p = molPos(m, t);
    m.dot.center(p.x, p.y);
    m.halo.center(p.x, p.y);
    c[p.x < neckCx ? 'L' : 'R'][m.sp]++;
  }
  lastCounts = c;

  var open = t > 0;
  boreClosed.opacity(open ? 0 : 0.95);
  boreOpen.opacity(open ? 0.95 : 0);
  knobClosed.opacity(open ? 0 : 1);
  knobOpen.opacity(open ? 1 : 0);

  var cap, letter;
  if (t <= 0) { cap = 'Stopcock closed'; letter = '(a)'; }
  else if (t < 70) { cap = 'Stopcock open'; letter = '(b)'; }
  else { cap = 'Some time after stopcock open'; letter = '(c)'; }
  capText.text(cap).center(neckCx, 352);
  letterText.text(letter).center(neckCx, 384);

  leftCount.text('H₂ ' + c.L.H2 + '   ·   O₂ ' + c.L.O2).center(lcx, 314);
  rightCount.text('H₂ ' + c.R.H2 + '   ·   O₂ ' + c.R.O2).center(rcx, 314);

  var ro = document.getElementById('countReadout');
  if (ro) {
    ro.innerHTML = 'Left bulb — H₂ ' + c.L.H2 + ', O₂ ' + c.L.O2 +
      '<br>Right bulb — H₂ ' + c.R.H2 + ', O₂ ' + c.R.O2;
  }
}

/* ── controls ─────────────────────────────────────────────── */
function setTime(v) {
  v = Math.max(0, Math.min(100, v));
  state.time = v;
  var inp = document.getElementById('timeElapsedInput');
  if (inp) inp.value = String(Math.round(v));
  var out = document.getElementById('timeElapsedVal');
  if (out) out.value = Math.round(v);
  render();
}

function update_timeElapsed(v) {
  if (state.playing) stopPlay();
  setTime(+v);
}

function toggle_massView(on) {
  state.mass = !!on;
  applyMassView();
  render();
}

var rafId = null, lastTs = 0;
function playTick(ts) {
  if (!state.playing) return;
  if (!lastTs) lastTs = ts;
  var dt = (ts - lastTs) / 1000; lastTs = ts;
  var nt = state.time + dt * (100 / 13);
  if (nt > 108) nt = 0;
  setTime(Math.min(nt, 100));
  state.time = nt > 100 ? nt : state.time;
  rafId = requestAnimationFrame(playTick);
}
function startPlay() {
  state.playing = true; lastTs = 0;
  if (state.time >= 100) setTime(0);
  document.getElementById('playBtn').textContent = '❚❚ Pause';
  rafId = requestAnimationFrame(playTick);
}
function stopPlay() {
  state.playing = false;
  if (rafId) cancelAnimationFrame(rafId);
  rafId = null;
  var b = document.getElementById('playBtn');
  if (b) b.textContent = '▶ Play diffusion';
}
function trigger_playDiffusion() {
  if (state.playing) stopPlay(); else startPlay();
}

/* ── demo steps ───────────────────────────────────────────── */
var steps = [
  {
    title: '(a) Stopcock closed',
    narration: 'H₂ fills the left bulb and O₂ the right, each perfectly confined. Two steep concentration gradients exist, but the closed valve forbids any exchange.',
    state: { timeElapsed: 0, mass: false }
  },
  {
    title: '(b) Stopcock open — first moments',
    narration: 'Open the valve and molecules immediately stream through the neck in both directions. Notice the asymmetry: several white H₂ molecules already reach the right bulb while only a few red O₂ molecules have crossed left.',
    state: { timeElapsed: 25, mass: false }
  },
  {
    title: 'Why H₂ moves ahead',
    narration: 'Mass view: at the same temperature both gases have the same average kinetic energy, so 2 g/mol H₂ molecules move far faster than 32 g/mol O₂ and spread roughly four times as quickly (rate ∝ 1/√M).',
    state: { timeElapsed: 45, mass: true }
  },
  {
    title: '(c) Approaching equilibrium',
    narration: 'Given enough time both species are distributed nearly uniformly across both bulbs. The gradients are gone, so net transfer stops — though individual molecules never stop crossing the neck.',
    state: { timeElapsed: 100, mass: false }
  }
];
var stepIdx = 0;

function setStep(i) {
  stopPlay();
  stepIdx = (i + steps.length) % steps.length;
  var s = steps[stepIdx];
  var cb = document.getElementById('massViewInput');
  if (cb) cb.checked = s.state.mass;
  state.mass = s.state.mass;
  applyMassView();
  setTime(s.state.timeElapsed);
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = s.title + '  (' + (stepIdx + 1) + '/' + steps.length + ')';
}
function nextStep() { setStep(stepIdx + 1); }
function prevStep() { setStep(stepIdx - 1); }

/* ── init ─────────────────────────────────────────────────── */
applyMassView();
setStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: Gases spread by random molecular motion from regions of high concentration to low until both bulbs are uniformly mixed — and the lighter gas (H₂) spreads faster than the heavier one (O₂).
KEY INSIGHT (what students should walk away understanding): Nothing pushes the gases together — random motion alone erases concentration gradients, and because equal temperature means equal average kinetic energy, the lighter H₂ molecules simply travel faster and mix sooner than the heavier O₂.
DEMO STEPS: 4 guided steps — implement the step player in #ui

