var figDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var FW = 720, FH = 440;
figDraw.viewbox(0, 0, FW, FH);

/* ── geometry ─────────────────────────────────────────────── */
var R = 118, cyB = 172, lcx = 196, rcx = 524;
var neckCx = (lcx + rcx) / 2;
var neckL = lcx + R - 8, neckR = rcx - R + 8;
var tubeHalf = 17;
var CORRIDOR = 54;

var GLASS = '#9cc2c4';
var GLASSDK = '#7fa8ab';
var GLASSFILL = '#d7e9e8';
var VALVE = '#cfe2e3';
