function lerp(a, b, u) { return { x: a.x + (b.x - a.x) * u, y: a.y + (b.y - a.y) * u }; }

function pathPoint(m, u) {
  u = Math.max(0, Math.min(1, u));
  u = u * u * (3 - 2 * u);
  var A = m.home, D = m.dest;
  var goRight = D.x > A.x;
  var B = { x: goRight ? neckL : neckR, y: cyB };
  var C = { x: goRight ? neckR : neckL, y: cyB };
  if (u < 0.35) return lerp(A, B, u / 0.35);
  if (u < 0.65) return lerp(B, C, (u - 0.35) / 0.30);
  return lerp(C, D, (u - 0.65) / 0.35);
}

function molPos(m, t) {
