    m.halo.center(p.x, p.y);
    c[p.x < neckCx ? 'L' : 'R'][m.sp]++;
  }
  lastCounts = c;

  var open = t > 0;
  boreClosed.opacity(open ? 0 : 0.95);
  boreOpen.opacity(open ? 0.95 : 0);
  handle.opacity(open ? 0 : 1);
  handleOpen.opacity(open ? 1 : 0);

  var l1, l2, letter;
  if (t <= 0) { l1 = 'Stopcock closed'; l2 = null; letter = '(a)'; }
  else if (t < 70) { l1 = 'Stopcock open'; l2 = null; letter = '(b)'; }
  else { l1 = 'Some time after'; l2 = 'Stopcock open'; letter = '(c)'; }

  capL1.text(l1).center(neckCx, 344);
  if (l2) { capL2.text(l2).center(neckCx, 368).opacity(1); } else { capL2.opacity(0); }
  letterText.text(letter).center(neckCx, 398);

  leftCount.text('H₂ ' + c.L.H2 + '   ·   O₂ ' + c.L.O2).center(lcx, 312);
  rightCount.text('H₂ ' + c.R.H2 + '   ·   O₂ ' + c.R.O2).center(rcx, 312);

