  {
    title: 'Why H₂ moves ahead',
    narration: 'Mass view: at the same temperature both gases have the same average kinetic energy, so 2 g/mol H₂ molecules move far faster than 32 g/mol O₂ and spread roughly four times as quickly (rate ∝ 1/√M).',
    state: { timeElapsed: 45, mass: true }
  },
  {
    title: '(c) Approaching equilibrium',
    narration: 'Given enough time both species are distributed nearly uniformly across both bulbs. The gradients are gone, so net transfer stops — though individual molecules never stop crossing the neck.',
    state: { timeElapsed: 100, mass: false }
  }
];
var stepIdx = 0;

function setStep(i) {
  stopPlay();
  stepIdx = (i + steps.length) % steps.length;
  var s = steps[stepIdx];
  var cb = document.getElementById('massViewInput');
  if (cb) cb.checked = s.state.mass;
  state.mass = s.state.mass;
  applyMassView();
  setTime(s.state.timeElapsed);
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = s.title + '  (' + (stepIdx + 1) + '/' + steps.length + ')';
}
function nextStep() { setStep(stepIdx + 1); }
function prevStep() { setStep(stepIdx - 1); }

/* ── init ─────────────────────────────────────────────────── */
applyMassView();
setStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: Gases spread by random molecular motion from regions of high concentration to low until both bulbs are uniformly mixed — and the lighter gas (H₂) spreads faster than the heavier one (O₂).
KEY INSIGHT (what students should walk away understanding): Nothing pushes the gases together — random motion alone erases concentration gradients, and because equal temperature means equal average kinetic energy, the lighter H₂ molecules simply travel faster and mix sooner than the heavier O₂.
DEMO STEPS: 4 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "Gases spread by random molecular motion from regions of high concentration to low until both bulbs are uniformly mixed — and the lighter gas (H₂) spreads faster than the heavier one (O₂).",
  "figureType": "diagram",
  "elements": [
    "Left spherical glass bulb (pale blue-green fill with lighter inner highlight, thick grey-teal outline)",
    "Right spherical glass bulb, identical styling",
    "Short horizontal neck/tube connecting the two bulbs",
    "Stopcock valve assembly drawn on the neck (barrel, handle/knob on top, stem below) with a visibly closed vs. open plug orientation",
    "White circular dots = H₂ molecules, initially all in the left bulb (~30)",
    "Red circular dots = O₂ molecules, initially all in the right bulb (~30)",
    "Label 'H₂' above the left bulb",
    "Label 'O₂' above the right bulb",
    "Caption text beneath the apparatus that changes with state: 'Stopcock closed' / 'Stopcock open' / 'Some time after stopcock open'",
    "Panel letter label (a) / (b) / (c) beneath the caption",
    "Optional molecule-count readout per bulb (H₂ left/right, O₂ left/right)",
    "Optional mass legend: 'H₂ = 2 g/mol (fast)' in white/blue, 'O₂ = 32 g/mol (slow)' in red",
    "Optional faint trail or speed halo on molecules when mass color-coding is on"
  ],
  "interactions": [
    {
      "id": "timeElapsed",
      "type": "slider",
      "teaches": "Mixing is continuous, not a jump between snapshots: every intermediate position shows partially overlapping populations, with the white H₂ front having travelled farther than the red O₂ front at the same instant.",
      "label": "Elapsed time after stopcock opens",
      "range": [
        0,
        100,
        1
      ],
      "default": 0
    },
    {
      "id": "playDiffusion",
      "type": "animation",
      "teaches": "Diffusion is driven by ceaseless random molecular motion — molecules do not 'aim' for the empty bulb, yet the net flow is always down the concentration gradient until it vanishes.",
      "label": "Play diffusion",
      "loop": true
    },
    {
      "id": "massView",
      "type": "toggle",
      "teaches": "Comparing the two species side by side shows H₂ populating the far bulb sooner than O₂ populates the near one, because rate of diffusion scales with 1/√(molar mass) — the seed of Graham's law.",
      "label": "View",
      "options": [
        "Both gases",
        "Color by molecular mass"
      ],
      "default": "Both gases"
    }
  ],
  "demo_steps": [
    {
      "title": "(a) Stopcock closed",
      "narration": "H₂ fills the left bulb and O₂ the right, each perfectly confined. Two steep concentration gradients exist, but the closed valve forbids any exchange.",
      "state": {
        "timeElapsed": 0,
        "massView": "Both gases"
      }
    },
    {
      "title": "(b) Stopcock open — first moments",
      "narration": "Open the valve and molecules immediately stream through the neck in both directions. Notice the asymmetry: several white H₂ molecules already reach the right bulb while only a few red O₂ molecules have crossed left.",
      "state": {
        "timeElapsed": 25,
        "massView": "Both gases"
      }
    },
    {
      "title": "Why H₂ moves ahead",
      "narration": "Switch to the mass view: at the same temperature both gases have the same average kinetic energy, so the 2 g/mol H₂ molecules move far faster than the 32 g/mol O₂ molecules and spread roughly four times as quickly.",
      "state": {
        "timeElapsed": 45,
        "massView": "Color by molecular mass"
      }
    },
    {
      "title": "(c) Approaching equilibrium",
      "narration": "Given enough time, both species are distributed nearly uniformly across both bulbs. The gradients are gone, so net transfer stops — though individual molecules never stop crossing the neck.",
      "state": {
        "timeElapsed": 100,
        "massView": "Both gases"
      }
    }
  ],
  "keyInsight": "Nothing pushes the gases together — random motion alone erases concentration gradients, and because equal temperature means equal average kinetic energy, the lighter H₂ molecules simply travel faster and mix sooner than the heavier O₂.",
  "reconstructionNotes": "Single apparatus centered on a white background: two equal-size pale blue-green spheres with soft inner highlights and thick grey-teal outlines, joined by a short horizontal neck carrying a grey-teal stopcock (knob above, stem below; rotate the plug 90° when open). Small white filled circles with faint outlines are H₂; slightly larger bright red filled circles are O₂ — scatter them irregularly, never on a grid. At t=0 all white dots sit left, all red dots sit right, packed fairly densely. As time advances, white dots should cross into the right bulb noticeably faster and in greater number than red dots cross left; by t=100 both colors are evenly intermixed in both bulbs. 'H₂' labels the left bulb, 'O₂' the right, both in dark grey serif-ish text above the spheres. A caption line beneath updates between 'Stopcock closed', 'Stopcock open', and 'Some time after stopcock open', with the panel letter (a)/(b)/(c) below it. In the mass-color view, add a small legend pairing white/blue with '2 g/mol — fast' and red with '32 g/mol — slow', and show per-bulb molecule counts so the learner can watch the numbers equalize at different rates."
}

The second image above is a screenshot of the PREVIOUS attempt's rendered output (not the source figure) — use it to see exactly what broke.

Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<span style="font-weight:600;font-size:12px">Diffusion: H₂ vs O₂</span>
<span id="demoNarration" style="display:block;font-size:11px;line-height:1.45;min-height:78px;color:#222"></span>
<span style="display:flex;align-items:center;gap:6px"><button onclick="prevStep()">◀</button><span id="stepLabel" style="flex:1;text-align:center;font-size:11px;color:#444"></span><button onclick="nextStep()">▶</button></span>
<label>Elapsed time after stopcock opens: <output id="timeElapsedVal">0</output>
<input id="timeElapsedInput" type="range" min="0" max="100" step="1" value="0" oninput="document.getElementById('timeElapsedVal').value=this.value;update_timeElapsed(+this.value)"></label>
<button id="playBtn" onclick="trigger_playDiffusion()">▶ Play diffusion</button>
<label><input id="massViewInput" type="checkbox" onchange="toggle_massView(this.checked)"> Color by molecular mass</label>
<span id="countReadout" style="font-size:11px;line-height:1.5;color:#333"></span>
<span style="font-size:10px;color:#666;line-height:1.4">The strip below the apparatus holds the three source panels (a)(b)(c) — click one to jump to that stage. Hover a molecule, a bulb, or the stopcock for details; click for an explanation.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var figDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var FW = 760, FH = 486;
figDraw.viewbox(0, 0, FW, FH);

/* ── geometry ─────────────────────────────────────────────── */
var R = 100, cyB = 155, lcx = 250, rcx = 510, neckCx = 380;
var tubeHalf = 14;
var neckL = lcx + R - 6, neckR = rcx - R + 6;
var CORRIDOR = 32;

var GLASS = '#a5c6c8';
var GLASSDK = '#84aaad';
var GLASSFILL = '#d9eae9';
var VALVE = '#cde2e3';
var RED = '#d8291c';
var REDDK = '#a81a12';
var H2STROKE = '#c2dbdb';

var FONTFAM = 'Helvetica Neue, Helvetica, Arial, sans-serif';

var hiGrad = figDraw.gradient('radial', function (add) {
  add.stop(0, '#ffffff', 0.82);
  add.stop(0.62, '#ffffff', 0.30);
  add.stop(1, '#ffffff', 0.0);
});

/* ── glass apparatus drawing ──────────────────────────────── */
function drawGlass(g) {
  var made = {};
  made.bulbL = g.circle(2 * R).center(lcx, cyB).fill(GLASSFILL).stroke({ color: GLASS, width: 3.4 });
  g.circle(1.15 * R).center(lcx - 0.30 * R, cyB - 0.34 * R).fill(hiGrad);
  made.bulbR = g.circle(2 * R).center(rcx, cyB).fill(GLASSFILL).stroke({ color: GLASS, width: 3.4 });
  g.circle(1.15 * R).center(rcx - 0.30 * R, cyB - 0.34 * R).fill(hiGrad);
  // neck fill: also erases the sphere outline where the tube joins
  g.rect(72, 2 * tubeHalf - 1).move(neckCx - 36, cyB - tubeHalf + 0.5).fill(GLASSFILL);
  g.line(neckCx - 35, cyB - tubeHalf, neckCx + 35, cyB - tubeHalf)
    .stroke({ color: GLASS, width: 3.2, linecap: 'round' });
  g.line(neckCx - 35, cyB + tubeHalf, neckCx + 35, cyB + tubeHalf)
    .stroke({ color: GLASS, width: 3.2, linecap: 'round' });
  return made;
}

/* rounded plug with a bulged middle */
var PLUG_PATH = (function () {
  var pw = 7, bw = 13.5, top = cyB - 21, bot = cyB + 21;
  return 'M' + (neckCx - pw) + ',' + top +
    ' C' + (neckCx - bw) + ',' + (cyB - 9) + ' ' + (neckCx - bw) + ',' + (cyB + 9) + ' ' + (neckCx - pw) + ',' + bot +
    ' L' + (neckCx + pw) + ',' + bot +
    ' C' + (neckCx + bw) + ',' + (cyB + 9) + ' ' + (neckCx + bw) + ',' + (cyB - 9) + ' ' + (neckCx + pw) + ',' + top + ' Z';
})();

function drawCock(parent, open) {
  var c = parent.group();
  // thin lower stem + small square foot
  c.rect(5, 12).move(neckCx - 2.5, cyB + 18).fill(VALVE).stroke({ color: GLASS, width: 1.8 });
  c.rect(16, 12).radius(2).move(neckCx - 8, cyB + 28).fill(VALVE).stroke({ color: GLASS, width: 2.1 });
  // bulged plug body
  c.path(PLUG_PATH).fill(VALVE).stroke({ color: GLASS, width: 2.4, linejoin: 'round' });
  // bore
  if (open) {
    c.rect(32, 9).radius(4.5).move(neckCx - 16, cyB - 4.5)
      .fill('#eef7f6').stroke({ color: GLASS, width: 1.2 });
  } else {
    c.rect(9, 25).radius(4.5).move(neckCx - 4.5, cyB - 12.5)
      .fill('#ffffff').opacity(0.95).stroke({ color: GLASS, width: 1.2 });
  }
  // thin upper stem
  c.rect(6, 15).move(neckCx - 3, cyB - 35).fill(VALVE).stroke({ color: GLASS, width: 1.8 });
  // flare + handle disc (turns 90° when open)
  if (open) {
    c.polygon([[neckCx - 5, cyB - 43], [neckCx + 5, cyB - 43], [neckCx + 3, cyB - 33], [neckCx - 3, cyB - 33]])
      .fill(VALVE).stroke({ color: GLASS, width: 1.8, linejoin: 'round' });
    c.ellipse(13, 9).center(neckCx, cyB - 45).fill(VALVE).stroke({ color: GLASS, width: 2.1 });
    c.line(neckCx - 3.5, cyB - 48, neckCx - 3.5, cyB - 42).stroke({ color: GLASSDK, width: 0.9, opacity: 0.7 });
    c.line(neckCx + 3.5, cyB - 48, neckCx + 3.5, cyB - 42).stroke({ color: GLASSDK, width: 0.9, opacity: 0.7 });
  } else {
    c.polygon([[neckCx - 13, cyB - 43], [neckCx + 13, cyB - 43], [neckCx + 4, cyB - 33], [neckCx - 4, cyB - 33]])
      .fill(VALVE).stroke({ color: GLASS, width: 1.9, linejoin: 'round' });
    c.ellipse(36, 10).center(neckCx, cyB - 45).fill(VALVE).stroke({ color: GLASS, width: 2.1 });
    [-12, -6, 0, 6, 12].forEach(function (dx) {
      c.line(neckCx + dx, cyB - 48.5, neckCx + dx, cyB - 41.5)
        .stroke({ color: GLASSDK, width: 0.9, opacity: 0.7 });
    });
  }
  return c;
}

/* ── main apparatus ───────────────────────────────────────── */
var glassLayer = figDraw.group();
var glass = drawGlass(glassLayer);
var cockLayer = figDraw.group();
var cockClosed = drawCock(cockLayer, false);
var cockOpen = drawCock(cockLayer, true).opacity(0);

/* ── evenly spread molecule sites ─────────────────────────── */
function mulberry32(a) {
  return function () {
    a |= 0; a = a + 0x6D2B79F5 | 0;
    var t = Math.imul(a ^ a >>> 15, 1 | a);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}
var rnd = mulberry32(20260922);

function bestCandidate(cx, n, maxR) {
  var pts = [], i, k;
  for (i = 0; i < n; i++) {
    var best = null, bestD = -1;
    for (k = 0; k < 22; k++) {
      var rr = maxR * Math.sqrt(rnd()), a = rnd() * Math.PI * 2;
      var p = { x: cx + rr * Math.cos(a), y: cyB + rr * Math.sin(a) };
      var d = Infinity;
      for (var j = 0; j < pts.length; j++) {
        var dx = p.x - pts[j].x, dy = p.y - pts[j].y, dd = dx * dx + dy * dy;
        if (dd < d) d = dd;
      }
      if (d > bestD) { bestD = d; best = p; }
    }
    pts.push(best);
  }
  return pts;
}
function shuffle(arr) {
  for (var i = arr.length - 1; i > 0; i--) {
    var j = Math.floor(rnd() * (i + 1)), t = arr[i]; arr[i] = arr[j]; arr[j] = t;
  }
  return arr;
}

var NH2 = 34, NO2 = 30;
var MAXR = 0.80 * R;                       // every site stays well inside the bulb
var sitesL = shuffle(bestCandidate(lcx, NH2 + NO2, MAXR));
var sitesR = shuffle(bestCandidate(rcx, NH2 + NO2, MAXR));

/* ── molecule model ───────────────────────────────────────── */
var mols = [];
function makeSpecies(sp, homeSites, destSites, k, count) {
  var qs = [], i;
  for (i = 0; i < count; i++) qs.push((i + 0.5) / count);
  shuffle(qs);
  for (i = 0; i < count; i++) {
    var q = qs[i];
    var tc = (q < 0.5) ? -(100 / k) * Math.log(1 - 2 * q) : Infinity;
    var isH = (sp === 'H2');
    mols.push({
      sp: sp, tCross: tc, isH: isH,
      home: homeSites[i], dest: destSites[i],
      amp: isH ? 3.4 + rnd() * 2.0 : 2.2 + rnd() * 1.4,
      f: isH ? 0.30 + rnd() * 0.18 : 0.12 + rnd() * 0.07,
      p1: rnd() * 6.283, p2: rnd() * 6.283
    });
  }
}
makeSpecies('H2', sitesL.slice(0, NH2), sitesR.slice(NO2, NO2 + NH2), 5.5, NH2);
makeSpecies('O2', sitesR.slice(0, NO2), sitesL.slice(NH2, NH2 + NO2), 1.6, NO2);

function lerp(a, b, u) { return { x: a.x + (b.x - a.x) * u, y: a.y + (b.y - a.y) * u }; }
function pathPoint(m, u) {
  u = Math.max(0, Math.min(1, u));
  u = u * u * (3 - 2 * u);
  var A = m.home, D = m.dest, goRight = D.x > A.x;
  var B = { x: goRight ? neckL : neckR, y: cyB };
  var C = { x: goRight ? neckR : neckL, y: cyB };
  if (u < 0.35) return lerp(A, B, u / 0.35);
  if (u < 0.65) return lerp(B, C, (u - 0.35) / 0.30);
  return lerp(C, D, (u - 0.65) / 0.35);
}
function molPos(m, t) {
  var tc = m.tCross, w = 8, base, transit = false;
  if (!isFinite(tc) || t <= tc - w) base = m.home;
  else if (t >= tc + w) base = m.dest;
  else { transit = true; base = pathPoint(m, (t - tc + w) / (2 * w)); }
  var amp = transit ? m.amp * 0.2 : m.amp;
  var x = base.x + amp * Math.sin(m.f * t + m.p1);
  var y = base.y + amp * Math.cos(m.f * 0.83 * t + m.p2);
  if (Math.abs(x - neckCx) < CORRIDOR) {
    y = Math.max(cyB - 7, Math.min(cyB + 7, y));
  } else {
    var c0 = (x < neckCx) ? lcx : rcx;
    var dx = x - c0, dy = y - cyB, d = Math.sqrt(dx * dx + dy * dy), lim = R - 10;
    if (d > lim) { x = c0 + dx / d * lim; y = cyB + dy / d * lim; }
  }
  return { x: x, y: y };
}

/* ── main molecule layer ──────────────────────────────────── */
var molLayer = figDraw.group();
for (var mi = 0; mi < mols.length; mi++) {
  (function (m) {
    var g = molLayer.group();
    m.halo = g.circle(m.isH ? 20 : 18).center(0, 0).fill(m.isH ? '#2f8fd8' : RED).opacity(0);
    m.dot = g.circle(m.isH ? 10.6 : 11.4).center(0, 0)
      .fill(m.isH ? '#ffffff' : RED)
      .stroke({ color: m.isH ? H2STROKE : RED, width: m.isH ? 0.8 : 0.8 });
    m.dot.css('cursor', 'pointer');
    var tip = m.isH ? 'H₂ — 2 g/mol · light and fast'
      : 'O₂ — 32 g/mol · heavy and about 4× slower';
    m.dot.on('mousemove', function (e) { showTooltip(tip, e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup(m.isH ? 'An H₂ molecule' : 'An O₂ molecule',
          m.isH
            ? 'At a given temperature every gas has the same average kinetic energy, ½mv². With a molar mass of only 2 g/mol, H₂ must move with a much larger average speed, so it wanders across the apparatus quickly.'
            : 'O₂ is 16× heavier than H₂ (32 vs 2 g/mol). The same average kinetic energy with a larger mass means v is smaller by √16 = 4, so O₂ diffuses about four times more slowly.');
      });
  })(mols[mi]);
}

/* ── labels, captions, legend ─────────────────────────────── */
var labelLayer = figDraw.group();
function mkText(parent, str, size, color, weight) {
  return parent.text(str).font({
    family: FONTFAM, size: size, weight: weight || 'normal', anchor: 'middle'
  }).fill(color || '#333');
}
mkText(labelLayer, 'H₂', 19, '#3a3a3a').center(lcx, 32);
mkText(labelLayer, 'O₂', 19, '#3a3a3a').center(rcx, 32);

var capL1 = mkText(labelLayer, 'Stopcock closed', 16, '#333').center(neckCx, 292);
var capL2 = mkText(labelLayer, '', 16, '#333').center(neckCx, 313).opacity(0);
var letterText = mkText(labelLayer, '(a)', 15, '#333').center(neckCx, 340);

var leftCount = mkText(labelLayer, '', 12, '#3b4a4a').center(lcx, 276).opacity(0);
var rightCount = mkText(labelLayer, '', 12, '#3b4a4a').center(rcx, 276).opacity(0);

var legend = labelLayer.group().opacity(0);
legend.rect(164, 48).radius(6).move(10, 258).fill('#ffffff').opacity(0.95)
  .stroke({ color: '#dde6e6', width: 1 });
legend.circle(19).center(28, 273).fill('#2f8fd8').opacity(0.28);
legend.circle(10.6).center(28, 273).fill('#ffffff').stroke({ color: '#2f6fbf', width: 1.3 });
legend.text('H₂  2 g/mol — fast').font({ family: FONTFAM, size: 11.5, anchor: 'start' })
  .fill('#245c9b').attr({ x: 44, y: 268 });
legend.circle(11.4).center(28, 293).fill(RED).stroke({ color: REDDK, width: 0.9 });
legend.text('O₂  32 g/mol — slow').font({ family: FONTFAM, size: 11.5, anchor: 'start' })
  .fill(REDDK).attr({ x: 44, y: 288 });

/* stopcock hit area (on top, small) */
var cockHit = labelLayer.rect(46, 104).move(neckCx - 23, cyB - 54).fill('#fff').opacity(0);
cockHit.css('cursor', 'pointer');
cockHit.on('mousemove', function (e) {
  showTooltip(state.time > 0
    ? 'Stopcock OPEN — the bore lines up with the tube'
    : 'Stopcock CLOSED — the bore sits across the tube, no exchange', e);
}).on('mouseleave', hideTooltip)
  .on('click', function () {
    showPopup('The stopcock',
      'Closed, the plug blocks the neck and the two steep concentration gradients cannot relax. Opened, the plug turns 90° so its bore lines up with the tube and molecules begin crossing in both directions at once — nothing pushes them, they simply wander.');
  });

/* bulb hover / click */
var lastCounts = { L: { H2: NH2, O2: 0 }, R: { H2: 0, O2: NO2 } };
function wireBulb(el, side) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) {
    var c = lastCounts[side];
    showTooltip((side === 'L' ? 'Left bulb' : 'Right bulb') + ': H₂ ' + c.H2 + ', O₂ ' + c.O2, e);
  }).on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup(side === 'L' ? 'Left bulb (started as pure H₂)' : 'Right bulb (started as pure O₂)',
        'Each bulb begins with one pure gas, so a steep concentration gradient exists across the neck. Random molecular motion alone carries molecules down that gradient until both bulbs hold roughly half of each gas; after that, crossings continue but the net transfer is zero.');
    });
}
wireBulb(glass.bulbL, 'L');
wireBulb(glass.bulbR, 'R');

/* ── source three-panel thumbnail strip ───────────────────── */
figDraw.line(24, 356, FW - 24, 356).stroke({ color: '#ececec', width: 1 });

var stripLayer = figDraw.group();
var PANEL_T = [0, 25, 100];
var PANEL_CAP = ['(a)  Stopcock closed', '(b)  Stopcock open', '(c)  Some time after'];
var PANEL_CX = [135, 380, 625];
var PSCALE = 0.40, PTY = 354;
var panelHL = [];

for (var pi = 0; pi < 3; pi++) {
  (function (i) {
    var hl = stripLayer.rect(200, 118).radius(7).move(PANEL_CX[i] - 100, 364)
      .fill('#f4fafd').opacity(0).stroke({ color: '#5aabf0', width: 1.4 });
    panelHL.push(hl);
    var tx = PANEL_CX[i] - 380 * PSCALE;
    var g = stripLayer.group().attr('transform', 'translate(' + tx + ',' + PTY + ') scale(' + PSCALE + ')');
    drawGlass(g);
    drawCock(g, PANEL_T[i] > 0);
    for (var k = 0; k < mols.length; k++) {
      var m = mols[k], p = molPos(m, PANEL_T[i]);
      g.circle(m.isH ? 10.6 : 11.4).center(p.x, p.y)
        .fill(m.isH ? '#ffffff' : RED)
        .stroke({ color: m.isH ? H2STROKE : RED, width: 0.8 });
    }
    mkText(stripLayer, PANEL_CAP[i], 11, '#444').center(PANEL_CX[i], 472);
    var hit = stripLayer.rect(200, 124).move(PANEL_CX[i] - 100, 362).fill('#fff').opacity(0);
    hit.css('cursor', 'pointer');
    hit.on('mousemove', function (e) {
      showTooltip(PANEL_CAP[i] + ' — click to show this stage in the large view', e);
    }).on('mouseleave', hideTooltip)
      .on('click', function () { stopPlay(); setTime(PANEL_T[i]); });
  })(pi);
}

/* ── state & rendering ────────────────────────────────────── */
var state = { time: 0, mass: false, playing: false };

function applyMassView() {
  var on = state.mass;
  legend.opacity(on ? 1 : 0);
  leftCount.opacity(on ? 1 : 0);
  rightCount.opacity(on ? 1 : 0);
  for (var i = 0; i < mols.length; i++) {
    var m = mols[i];
    m.halo.opacity(on ? (m.isH ? 0.30 : 0.13) : 0);
    m.dot.stroke({
      color: on ? (m.isH ? '#2f6fbf' : REDDK) : (m.isH ? H2STROKE : RED),
      width: on ? 1.3 : 0.8
    });
  }
}

function render() {
  var t = state.time, i;
  var c = { L: { H2: 0, O2: 0 }, R: { H2: 0, O2: 0 } };
  for (i = 0; i < mols.length; i++) {
    var m = mols[i], p = molPos(m, t);
    m.dot.center(p.x, p.y);
    m.halo.center(p.x, p.y);
    c[p.x < neckCx ? 'L' : 'R'][m.sp]++;
  }
  lastCounts = c;

  var open = t > 0;
  cockClosed.opacity(open ? 0 : 1);
  cockOpen.opacity(open ? 1 : 0);

  var l1, l2, letter, active;
  if (t <= 0) { l1 = 'Stopcock closed'; l2 = null; letter = '(a)'; active = 0; }
  else if (t < 70) { l1 = 'Stopcock open'; l2 = null; letter = '(b)'; active = 1; }
  else { l1 = 'Some time after'; l2 = 'Stopcock open'; letter = '(c)'; active = 2; }

  capL1.text(l1).center(neckCx, l2 ? 292 : 296);
  if (l2) { capL2.text(l2).center(neckCx, 313).opacity(1); } else { capL2.opacity(0); }
  letterText.text(letter).center(neckCx, 340);
  for (i = 0; i < 3; i++) panelHL[i].opacity(i === active ? 1 : 0);

  leftCount.text('H₂ ' + c.L.H2 + '   ·   O₂ ' + c.L.O2).center(lcx, 276);
  rightCount.text('H₂ ' + c.R.H2 + '   ·   O₂ ' + c.R.O2).center(rcx, 276);

  var ro = document.getElementById('countReadout');
  if (ro) {
    ro.innerHTML = 'Left bulb — H₂ ' + c.L.H2 + ', O₂ ' + c.L.O2 +
      '<br>Right bulb — H₂ ' + c.R.H2 + ', O₂ ' + c.R.O2;
  }
}

/* ── controls ─────────────────────────────────────────────── */
function setTime(v) {
  v = Math.max(0, Math.min(100, v));
  state.time = v;
  var inp = document.getElementById('timeElapsedInput');
  if (inp) inp.value = String(Math.round(v));
  var out = document.getElementById('timeElapsedVal');
  if (out) out.value = Math.round(v);
  render();
}
function update_timeElapsed(v) { if (state.playing) stopPlay(); setTime(+v); }
function toggle_massView(on) { state.mass = !!on; applyMassView(); render(); }

var rafId = null, lastTs = 0, holdT = 0;
function playTick(ts) {
  if (!state.playing) return;
  if (!lastTs) lastTs = ts;
  var dt = (ts - lastTs) / 1000; lastTs = ts;
  holdT += dt * (100 / 13);
  if (holdT > 114) holdT = 0;
  setTime(Math.min(holdT, 100));
  rafId = requestAnimationFrame(playTick);
}
function startPlay() {
  state.playing = true; lastTs = 0;
  holdT = (state.time >= 100) ? 0 : state.time;
  document.getElementById('playBtn').textContent = '❚❚ Pause';
  rafId = requestAnimationFrame(playTick);
}
function stopPlay() {
  state.playing = false;
  if (rafId) cancelAnimationFrame(rafId);
  rafId = null;
  var b = document.getElementById('playBtn');
  if (b) b.textContent = '▶ Play diffusion';
}
function trigger_playDiffusion() { if (state.playing) stopPlay(); else startPlay(); }

/* ── demo steps ───────────────────────────────────────────── */
var steps = [
  {
    title: '(a) Stopcock closed',
    narration: 'H₂ fills the left bulb and O₂ the right, each perfectly confined — the connecting tube is empty. Two steep concentration gradients exist, but the closed valve forbids any exchange.',
    state: { timeElapsed: 0, mass: false }
  },
  {
    title: '(b) Stopcock open — first moments',
    narration: 'Open the valve and molecules immediately stream through the neck in both directions. Notice the asymmetry: many white H₂ molecules already reach the right bulb while only a few red O₂ molecules have crossed left.',
    state: { timeElapsed: 25, mass: false }
  },
  {
    title: 'Why H₂ moves ahead',
    narration: 'Mass view: at the same temperature both gases have the same average kinetic energy, so 2 g/mol H₂ molecules move far faster than 32 g/mol O₂ and spread roughly four times as quickly (rate ∝ 1/√M).',
    state: { timeElapsed: 45, mass: true }
  },
  {
    title: '(c) Approaching equilibrium',
    narration: 'Given enough time both species are spread nearly uniformly across both bulbs. The gradients are gone, so net transfer stops — though individual molecules never stop crossing the neck.',
    state: { timeElapsed: 100, mass: false }
  }
];
var stepIdx = 0;
function setStep(i) {
  stopPlay();
  stepIdx = (i + steps.length) % steps.length;
  var s = steps[stepIdx];
  var cb = document.getElementById('massViewInput');
  if (cb) cb.checked = s.state.mass;
  state.mass = s.state.mass;
  applyMassView();
  setTime(s.state.timeElapsed);
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = s.title + '  (' + (stepIdx + 1) + '/' + steps.length + ')';
}
function nextStep() { setStep(stepIdx + 1); }
function prevStep() { setStep(stepIdx - 1); }

/* ── init ─────────────────────────────────────────────────── */
applyMassView();
setStep(0);
window.__markRendered();
